import * as fs from 'fs';
import * as path from 'path';

const ROOT = '__FIXTURE_DIR__/project_tree';

interface FileInfo {
  relPath: string;
  lines: number;
  chars: number;
}

type ExtensionMap = Map<string, FileInfo[]>;

function walk(dir: string, root: string, visited: Set<string>, result: ExtensionMap): void {
  let entries: fs.Dirent[];
  try {
    entries = fs.readdirSync(dir, { withFileTypes: true });
  } catch {
    return;
  }

  for (const entry of entries) {
    const fullPath = path.join(dir, entry.name);

    let stats: fs.Stats;
    try {
      stats = fs.lstatSync(fullPath);
    } catch {
      continue;
    }

    if (stats.isSymbolicLink()) {
      continue;
    }

    if (stats.isDirectory()) {
      let resolved: string;
      try {
        resolved = fs.realpathSync(fullPath);
      } catch {
        continue;
      }
      if (visited.has(resolved)) continue;
      visited.add(resolved);
      walk(fullPath, root, visited, result);
    } else if (stats.isFile()) {
      const relPath = path.relative(root, fullPath).split(path.sep).join('/');
      const content = fs.readFileSync(fullPath, 'utf-8');
      let lines: number;
      if (content.length === 0) {
        lines = 0;
      } else {
        lines = content.split('\n').length;
        if (content.endsWith('\n')) lines--;
      }
      const chars = stats.size;
      const ext = path.extname(entry.name);

      if (!result.has(ext)) {
        result.set(ext, []);
      }
      result.get(ext)!.push({ relPath, lines, chars });
    }
  }
}

