#include <stdlib.h>
#include <string.h>

static char *run_cmd(const char *cmd)
{
    FILE *fp = popen(cmd, "r");
    if (!fp)
        return NULL;

    size_t cap = 4096;
    char *buf = (char *)malloc(cap);
    if (!buf) {
        pclose(fp);
        return NULL;
    }
    buf[0] = '\0';

    size_t total = 0;
    while (fgets(buf + total, (int)(cap - total), fp)) {
        size_t len = strlen(buf + total);
        total += len;
        if (total >= cap - 1) {
            cap *= 2;
            char *nb = (char *)realloc(buf, cap);
            if (!nb) {
                free(buf);
                pclose(fp);
                return NULL;
            }
            buf = nb;
        }
    }

    pclose(fp);

    while (total > 0 &&
           (buf[total - 1] == '\n' || buf[total - 1] == '\r' ||
            buf[total - 1] == ' '  || buf[total - 1] == '\t')) {
        buf[--total] = '\0';
    }

    return buf;
}

