    static int[][] multiply(int[][] A, int[][] B) {
        int n = A.length;
        int[][] C = new int[n][n];
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                for (int k = 0; k < n; k++)
                    C[i][j] += A[i][k] * B[k][j];
        return C;
    }

    static int determinant(int[][] M) {
        int n = M.length;
        if (n == 1) return M[0][0];
        if (n == 2) return M[0][0] * M[1][1] - M[0][1] * M[1][0];
        int det = 0;
        for (int j = 0; j < n; j++) {
            int[][] minor = new int[n - 1][n - 1];
            for (int i = 1; i < n; i++) {
                int col = 0;
                for (int k = 0; k < n; k++) {
                    if (k == j) continue;
                    minor[i - 1][col++] = M[i][k];
                }
            }
            det += (j % 2 == 0 ? 1 : -1) * M[0][j] * determinant(minor);
        }
        return det;
    }

