            for k in 0..n {
                c[i][j] += a[i][k] as i64 * b[k][j] as i64;
            }
        }
    }

    let det = c[0][0] * (c[1][1] * c[2][2] - c[1][2] * c[2][1])
             - c[0][1] * (c[1][0] * c[2][2] - c[1][2] * c[2][0])
             + c[0][2] * (c[1][0] * c[2][1] - c[1][1] * c[2][0]);

    print!("=== Matrix Operations ===\n");
    println!();
    println!("Matrix A:");
    for row in &a {
        let formatted: Vec<String> = row.iter().map(|v| format!("{:4}", v)).collect();
        print!("  {}\n", formatted.join(" "));
    }
    println!();
    println!("Matrix B:");
    for row in &b {
        let formatted: Vec<String> = row.iter().map(|v| format!("{:4}", v)).collect();
        print!("  {}\n", formatted.join(" "));
    }
    println!();
    println!("A x B =");
    for row in &c {
        let formatted: Vec<String> = row.iter().map(|v| format!("{:4}", v)).collect();
        print!("  {}\n", formatted.join(" "));
    }
    println!();
    println!("Determinant: {}", det);
}
